await page.goto('/ops/radar');
const candidates = [
  page.getByRole('feed'),
  page.getByRole('list', { name: /feed|radar/i }),
  page.getByRole('region', { name: /feed|radar/i }),
  page.getByRole('list'),
];
let feed = candidates[candidates.length - 1].first();
for (const c of candidates) {
  if ((await c.count()) > 0) { feed = c.first(); break; }
}
await expect(feed).toBeVisible();
await expect(feed).toHaveCSS('flex-direction', 'column');
